import heapq


def topo_sort(graph: dict[str, list[str]]) -> list[str]:
    vertices: set[str] = set(graph.keys())
    for neighbors in graph.values():
        for v in neighbors:
            vertices.add(v)

    in_degree: dict[str, int] = {v: 0 for v in vertices}
    for u, neighbors in graph.items():
        for v in neighbors:
            in_degree[v] += 1

    heap: list[str] = [v for v in vertices if in_degree[v] == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(vertices):
        raise ValueError("cycle detected")

    return result
